def longest_increasing_subsequence(seq: list[int]) -> int:
    n: int = len(seq)
    if n == 0:
        return 0
    best: list[int] = []
    i: int = 0
    while i < n:
        best.append(1)
        i = i + 1
    i = 1
    while i < n:
        j: int = 0
        while j < i:
            if seq[j] < seq[i] and best[j] + 1 > best[i]:
                best[i] = best[j] + 1
            j = j + 1
        i = i + 1
    # compute max manually (max requires exactly two arguments)
    max_val: int = best[0]
    k: int = 1
    while k < n:
        if best[k] > max_val:
            max_val = best[k]
        k = k + 1
    return max_val
